import{_ as o,o as t,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"BÁO CÁO HOÀN THÀNH TÁC VỤ: DA-E08-02","description":"","frontmatter":{},"headers":[],"relativePath":"wireframe/components-report.md","filePath":"wireframe/components-report.md"}'),i={name:"wireframe/components-report.md"};function c(d,e,r,l,s,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="bao-cao-hoan-thanh-tac-vu-da-e08-02" tabindex="-1">BÁO CÁO HOÀN THÀNH TÁC VỤ: DA-E08-02 <a class="header-anchor" href="#bao-cao-hoan-thanh-tac-vu-da-e08-02" aria-label="Permalink to &quot;BÁO CÁO HOÀN THÀNH TÁC VỤ: DA-E08-02&quot;">​</a></h1><p><strong>Tên tác vụ:</strong> Design Component System (Button, Input, Modal, Table, Badge, Toast styles)<br><strong>Mức độ ưu tiên:</strong> 🔴 Critical (Nghiêm trọng)<br><strong>Mục tiêu:</strong> Định nghĩa các Visual Design Tokens và Component Variants đồng bộ cho Web-Dashboard của hệ thống BrandHub để tránh các quyết định thiết kế ngẫu hứng từ phía lập trình viên.</p><hr><h2 id="📌-checklist-nghiem-thu-acceptance-criteria" tabindex="-1">📌 Checklist Nghiệm thu (Acceptance Criteria) <a class="header-anchor" href="#📌-checklist-nghiem-thu-acceptance-criteria" aria-label="Permalink to &quot;📌 Checklist Nghiệm thu (Acceptance Criteria)&quot;">​</a></h2><ul><li>[x] <strong>Design Tokens:</strong> Định nghĩa đầy đủ các biến màu sắc (primary, secondary, destructive), typography (fonts, sizes, weights), spacing, border radius và shadow levels.</li><li>[x] <strong>Component Variants:</strong><ul><li>[x] <strong>Button:</strong> Đầy đủ các biến thể (primary/default, secondary, destructive, ghost, outline) và các kích thước (sm, default, lg, icon).</li><li>[x] <strong>Input:</strong> Thiết kế đầy đủ cho các trạng thái default, disabled, và error (aria-invalid).</li><li>[x] <strong>Modal/Dialog:</strong> Tương tác linh hoạt, kết nối visual đồng bộ từ Radix UI.</li><li>[x] <strong>Table &amp; Pagination:</strong> Hỗ trợ cấu trúc bảng, sort headers và phân trang (Pagination) chuẩn hóa.</li><li>[x] <strong>Badge (PostStatus):</strong> Định nghĩa đúng mã màu cho các trạng thái: <code>DRAFT</code>, <code>PENDING_REVIEW</code>, <code>APPROVED</code>, <code>SCHEDULED</code>, <code>PUBLISHED</code>, <code>FAILED</code>, và <code>REJECTED</code>.</li><li>[x] <strong>Toast:</strong> Đầy đủ các phong cách thông báo <code>success</code>, <code>error</code>, <code>warning</code>, <code>info</code> từ Sonner.</li></ul></li><li>[x] <strong>Figma-to-Code Alignment:</strong> Đặt tên và cấu trúc biến CSS đồng nhất 100% với Figma variables và chuẩn <code>shadcn/ui</code>.</li></ul><hr><h2 id="🛠-chi-tiet-trien-khai-ky-thuat" tabindex="-1">🛠 Chi Tiết Triển Khai Kỹ Thuật <a class="header-anchor" href="#🛠-chi-tiet-trien-khai-ky-thuat" aria-label="Permalink to &quot;🛠 Chi Tiết Triển Khai Kỹ Thuật&quot;">​</a></h2><h3 id="_1-he-thong-design-tokens-css-variables" tabindex="-1">1. Hệ thống Design Tokens (CSS Variables) <a class="header-anchor" href="#_1-he-thong-design-tokens-css-variables" aria-label="Permalink to &quot;1. Hệ thống Design Tokens (CSS Variables)&quot;">​</a></h3><p>Được cấu hình tập trung trong tệp tin [theme.css] tương thích hoàn hảo với cơ chế biên dịch của Tailwind CSS v4.</p><ul><li><strong>Bảng màu chủ đạo (Colors):</strong><ul><li><code>--primary</code>: <code>#0a0a0a</code> | <code>--primary-foreground</code>: <code>#fafafa</code></li><li><code>--secondary</code>: <code>#f4f4f5</code> | <code>--secondary-foreground</code>: <code>#0a0a0a</code></li><li><code>--destructive</code>: <code>#ef4444</code> | <code>--destructive-foreground</code>: <code>#ffffff</code></li><li><code>--background</code>: <code>#fafafa</code> | <code>--foreground</code>: <code>#0a0a0a</code></li><li><code>--border</code>: <code>#e4e4e7</code></li><li><code>--ring</code> (Brand Orange): <code>#f05a28</code></li></ul></li><li><strong>Typography:</strong><ul><li>Sans-serif font family: <code>&#39;Inter&#39;, system-ui, sans-serif</code> (đảm bảo hiển thị hiện đại, tinh tế).</li><li>Monospace font family: <code>&#39;Geist Mono&#39;, &#39;JetBrains Mono&#39;, monospace</code>.</li></ul></li><li><strong>Border Radius:</strong><ul><li><code>--radius-lg</code>: <code>0.5rem</code> (bo góc tiêu chuẩn cho các thẻ Card, Modal).</li><li><code>--radius-md</code> và <code>--radius-sm</code> tự động tính toán co lại theo tỷ lệ của <code>--radius</code>.</li></ul></li></ul><hr><h3 id="_2-cac-thanh-phan-giao-dien-ui-components" tabindex="-1">2. Các Thành phần Giao diện (UI Components) <a class="header-anchor" href="#_2-cac-thanh-phan-giao-dien-ui-components" aria-label="Permalink to &quot;2. Các Thành phần Giao diện (UI Components)&quot;">​</a></h3><p>Tất cả các components đều được xây dựng trong thư mục [src/app/components/ui/].</p><h4 id="a-button-button-tsx" tabindex="-1">A. Button ([button.tsx]) <a class="header-anchor" href="#a-button-button-tsx" aria-label="Permalink to &quot;A. Button ([button.tsx])&quot;">​</a></h4><p>Hỗ trợ đầy đủ các thuộc tính trạng thái và kích cỡ thông qua thư viện <code>class-variance-authority</code>:</p><ul><li><strong>Variants:</strong><ul><li><code>default</code>: Sử dụng màu <code>--primary</code> chủ đạo.</li><li><code>secondary</code>: Sử dụng nền <code>--secondary</code>.</li><li><code>destructive</code>: Nền đỏ <code>--destructive</code> cho các tác vụ nguy hiểm.</li><li><code>outline</code>: Viền mảnh <code>--border</code>, phù hợp nút phụ.</li><li><code>ghost</code>: Nền trong suốt, đổi màu khi hover.</li></ul></li><li><strong>Sizes:</strong> <code>default</code> (h-9), <code>sm</code> (h-8), <code>lg</code> (h-10), <code>icon</code> (h-9, tỉ lệ 1:1).</li></ul><h4 id="b-input-input-tsx" tabindex="-1">B. Input ([input.tsx]) <a class="header-anchor" href="#b-input-input-tsx" aria-label="Permalink to &quot;B. Input ([input.tsx])&quot;">​</a></h4><ul><li>Định nghĩa rõ ràng trạng thái <strong>Disabled</strong> (<code>disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50</code>).</li><li>Tích hợp cơ chế cảnh báo lỗi thông minh <strong>Error</strong> qua <code>aria-invalid</code> (<code>aria-invalid:border-destructive aria-invalid:ring-destructive/20</code>), giúp liên kết chặt chẽ với các thư viện quản lý Form như <code>react-hook-form</code>.</li></ul><h4 id="c-modal-dialog-dialog-tsx" tabindex="-1">C. Modal/Dialog ([dialog.tsx]) <a class="header-anchor" href="#c-modal-dialog-dialog-tsx" aria-label="Permalink to &quot;C. Modal/Dialog ([dialog.tsx])&quot;">​</a></h4><ul><li>Xây dựng trên nền tảng Radix UI <code>@radix-ui/react-dialog</code>.</li><li>Đảm bảo hiệu ứng làm mờ nền (<code>bg-black/50</code>) và hiệu ứng chuyển cảnh mượt mà (<code>data-[state=open]:animate-in zoom-in-95</code>).</li></ul><h4 id="d-table-pagination-table-tsx-pagination-tsx" tabindex="-1">D. Table &amp; Pagination ([table.tsx] &amp; [pagination.tsx]) <a class="header-anchor" href="#d-table-pagination-table-tsx-pagination-tsx" aria-label="Permalink to &quot;D. Table &amp; Pagination ([table.tsx] &amp; [pagination.tsx])&quot;">​</a></h4><ul><li>Hỗ trợ đầy đủ tập hợp các thẻ con: <code>TableHeader</code>, <code>TableBody</code>, <code>TableRow</code>, <code>TableHead</code>, <code>TableCell</code>.</li><li><strong>Sort Headers:</strong> Tích hợp trực tiếp và sạch sẽ trong <code>&lt;TableHead&gt;</code> qua các nút bấm phụ và icon như <code>ArrowUpDown</code>.</li><li><strong>Pagination:</strong> Cung cấp bộ nút chuyển tiếp nhanh (<code>PaginationPrevious</code>, <code>PaginationNext</code>, <code>PaginationLink</code>, và <code>PaginationEllipsis</code>).</li></ul><h4 id="e-badge-badge-tsx" tabindex="-1">E. Badge ([badge.tsx]) <a class="header-anchor" href="#e-badge-badge-tsx" aria-label="Permalink to &quot;E. Badge ([badge.tsx])&quot;">​</a></h4><p>Đã được bổ sung và hoàn thiện ánh xạ trực tiếp sang các giá trị cụ thể của enum <code>PostStatus</code>:</p><ul><li><strong>DRAFT / draft:</strong> Màu xám nhạt (<code>bg-zinc-100 text-zinc-800</code>).</li><li><strong>PENDING_REVIEW / pending_review:</strong> Màu vàng cam hổ phách (<code>bg-amber-100 text-amber-800</code>).</li><li><strong>APPROVED / approved:</strong> Màu xanh dương (<code>bg-blue-100 text-blue-800</code>).</li><li><strong>SCHEDULED / scheduled:</strong> Màu tím mộng mơ (<code>bg-purple-100 text-purple-800</code>).</li><li><strong>PUBLISHED / published:</strong> Màu xanh lá cây (<code>bg-green-100 text-green-800</code>).</li><li><strong>FAILED / failed:</strong> Màu đỏ tươi cảnh báo (<code>bg-red-100 text-red-800</code>).</li><li><strong>REJECTED / rejected:</strong> Màu đỏ tối/sẫm (<code>bg-red-900 text-red-50</code> cho Light mode, <code>bg-red-950 text-red-200</code> cho Dark mode).</li></ul><h4 id="f-toast-sonner-tsx" tabindex="-1">F. Toast ([sonner.tsx]) <a class="header-anchor" href="#f-toast-sonner-tsx" aria-label="Permalink to &quot;F. Toast ([sonner.tsx])&quot;">​</a></h4><ul><li>Dựa trên nền tảng thư viện <code>sonner</code> nổi tiếng cho các hiệu ứng trượt nhanh gọn, thông minh.</li><li>Định kiểu rõ ràng cho 4 trạng thái phản hồi hệ thống: <code>success</code>, <code>error</code>, <code>warning</code>, <code>info</code>.</li></ul>',27)])])}const p=o(i,[["render",c]]);export{u as __pageData,p as default};
